import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_transposed_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void matmul_transposed_kernel(
    const scalar_t* A,
    const scalar_t* B,
    scalar_t* C,
    int M,
    int K,
    int N) {

    const int TILE = 16;
    const int TILE_K = 16;

    __shared__ scalar_t B_shared[TILE][TILE_K+1];  // +1 to avoid bank conflicts
    __shared__ scalar_t A_shared[TILE][TILE_K+1];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int i0 = blockIdx.x * TILE;
    int j0 = blockIdx.y * TILE;

    scalar_t sum = 0;

    for (int k_base = 0; k_base < K; k_base += TILE_K) {
        // Load B tile (N x K)
        int B_row = j0 + ty;
        int B_col = k_base + tx;
        if (B_row < N && B_col < K) {
            B_shared[ty][tx] = B[B_row * K + B_col];
        } else {
            B_shared[ty][tx] = 0;
        }

        // Load and transpose A tile (K x M)
        int A_row = k_base + ty;
        int A_col = i0 + tx;
        if (A_row < K && A_col < M) {
            A_shared[tx][ty] = A[A_row * M + A_col];
        } else {
            A_shared[tx][ty] = 0;
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            sum += B_shared[ty][kk] * A_shared[tx][kk];
        }

        __syncthreads();
    }

    if ((i0 + tx) < M && (j0 + ty) < N) {
        C[(i0 + tx) * N + (j0 + ty)] = sum;
    }
}

torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B) {
    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((M + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    AT_DISPATCH_FLOATING_TYPES(A.scalar_type(), "matmul_transposed_cuda", ([&] {
        matmul_transposed_kernel<scalar_t><<<grid, block>>>(
            A.data_ptr<scalar_t>(),
            B.data_ptr<scalar_t>(),
            C.data_ptr<scalar_t>(),
            M, K, N
        );
    }));

    return C;
}
"""

matmul_transposed_cpp_source = "torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B);"

matmul_transposed = load_inline(
    name="matmul_transposed",
    cpp_sources=matmul_transposed_cpp_source,
    cuda_sources=matmul_transposed_source,
    functions=["matmul_transposed_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_transposed = matmul_transposed

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_transposed.matmul_transposed_cuda(A, B)
